class Solution {
public:
    vector<int> sortArray(vector<int>& nums) {
        const int OFFSET = 50000;
        const int RANGE = 100001;
        vector<int> count(RANGE, 0);
        for (int x : nums) {
            count[x + OFFSET]++;
        }
        vector<int> result;
        result.reserve(nums.size());
        for (int v = 0; v < RANGE; v++) {
            int c = count[v];
            int value = v - OFFSET;
            for (int i = 0; i < c; i++) {
                result.push_back(value);
            }
        }
        return result;
    }
};
